import{_ as n,o as e,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Zaman Pra-Jangkar","description":"","frontmatter":{},"headers":[],"relativePath":"id/71-前锚点时代.md","filePath":"id/71-前锚点时代.md"}'),t={name:"id/71-前锚点时代.md"};function s(d,a,k,u,m,g){return e(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="zaman-pra-jangkar" tabindex="-1">Zaman Pra-Jangkar <a class="header-anchor" href="#zaman-pra-jangkar" aria-label="Permalink to &quot;Zaman Pra-Jangkar&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>71</td></tr><tr><td>Modul</td><td>Zaman Sejarah dan Peristiwa Penting</td></tr><tr><td>Kata Kunci Inti</td><td>Zaman pra-jangkar, sistem predator, kegagalan peradaban, zaman kegelapan, kekacauan hukum</td></tr></tbody></table><h2 id="_1-karakteristik-dasar-zaman-pra-jangkar" tabindex="-1">1. Karakteristik Dasar Zaman Pra-Jangkar <a class="header-anchor" href="#_1-karakteristik-dasar-zaman-pra-jangkar" aria-label="Permalink to &quot;1. Karakteristik Dasar Zaman Pra-Jangkar&quot;">​</a></h2><p>Zaman Pra-Jangkar adalah zaman terpanjang dan paling gelap dalam sejarah Hengyuanzhou. Pada zaman ini, tidak ada mekanisme jangkar yang terpadu di alam semesta, hukum-hukum dasar berada dalam keadaan tersebar secara alami, dan distribusi energi serta sumber daya sepenuhnya mengikuti hukum rimba &quot;yang kuat mendapatkannya&quot;. Sistem kultivasi predator adalah penguasa mutlak zaman ini; metode kultivasi dimonopoli oleh sedikit orang kuat dan sekte, dan makhluk biasa di lapisan bawah hampir tidak memiliki jalur evolusi formal.</p><p>Karakteristik inti Zaman Pra-Jangkar dapat diringkas sebagai &quot;lima ketiadaan&quot;:</p><ul><li><strong>Tanpa jangkar</strong>: Tidak ada jangkar hukum yang stabil, aliran energi kacau, dan penghalang antar-bidang rapuh</li><li><strong>Tanpa tatanan</strong>: Tidak ada sistem peradaban yang terpadu, perang terus-menerus antar-bidang, dan pemusnahan ras sering terjadi</li><li><strong>Tanpa jalur</strong>: Tidak ada teknologi komunikasi dan transportasi antar-bidang, dan bidang-bidang pada dasarnya terisolasi satu sama lain</li><li><strong>Tanpa jaminan</strong>: Tidak ada sistem jaminan publik seperti pendidikan, kesehatan, dan perumahan, dan kelangsungan hidup sepenuhnya bergantung pada kekuatan individu</li><li><strong>Tanpa harapan</strong>: Saluran evolusi makhluk di lapisan bawah sepenuhnya terblokir, dan stratifikasi sosial mencapai titik ekstrem</li></ul><h2 id="_2-mekanisme-kerja-sistem-kultivasi-predator" tabindex="-1">2. Mekanisme Kerja Sistem Kultivasi Predator <a class="header-anchor" href="#_2-mekanisme-kerja-sistem-kultivasi-predator" aria-label="Permalink to &quot;2. Mekanisme Kerja Sistem Kultivasi Predator&quot;">​</a></h2><p>Sistem kultivasi Zaman Pra-Jangkar memiliki predasi sebagai mekanisme kerja inti. Logika dasarnya adalah: energi dasar alam semesta terbatas, dan evolusi individu pasti terjadi dengan mengorbankan energi orang lain. Orang-orang kuat mencapai kenaikan mereka sendiri dengan memangsa energi, keberuntungan, bahkan esensi orang-orang lemah, sementara orang-orang lemah menjadi &quot;sumber daya kultivasi&quot; bagi orang-orang kuat.</p><p>Bentuk-bentuk khas sistem predator meliputi:</p><table tabindex="0"><thead><tr><th>Jenis Predasi</th><th>Cara Kerja</th><th>Kerusakan pada Alam Semesta</th></tr></thead><tbody><tr><td>Predasi energi</td><td>Menyedot langsung energi kultivasi makhluk lain</td><td>Menyebabkan kematian individu atau hilangnya kultivasi sepenuhnya</td></tr><tr><td>Predasi keberuntungan</td><td>Melalui mantra atau ritual, merebut keberuntungan dan kesempatan orang lain</td><td>Merusak keseimbangan kausal, memicu bencana tingkat bidang</td></tr><tr><td>Predasi esensi</td><td>Memangsa fragmen hukum dasar makhluk lain</td><td>Menyebabkan hilangnya potensi evolusi yang tidak dapat dipulihkan</td></tr><tr><td>Predasi bidang</td><td>Orang kuat menaklukkan seluruh bidang dan menggunakan makhluk di bidang itu sebagai sumber daya kultivasi</td><td>Menyebabkan kepunahan peradaban dan penggurunan bidang</td></tr><tr><td>Predasi hukum</td><td>Merebut secara paksa kendali hukum dasar suatu bidang</td><td>Merusak jaringan hukum, memicu keruntuhan ruang</td></tr></tbody></table><p>Sistem predator dapat, dalam jangka pendek, menciptakan beberapa makhluk tertinggi, tetapi dalam jangka panjang, ia terus mengonsumsi potensi evolusi alam semesta, menyebabkan peningkatan entropi umum alam semesta yang dipercepat dan kegagalan peradaban yang sering terjadi.</p><h2 id="_3-kegagalan-peradaban-dan-kehancuran-siklus" tabindex="-1">3. Kegagalan Peradaban dan Kehancuran Siklus <a class="header-anchor" href="#_3-kegagalan-peradaban-dan-kehancuran-siklus" aria-label="Permalink to &quot;3. Kegagalan Peradaban dan Kehancuran Siklus&quot;">​</a></h2><p>Fenomena sejarah yang paling menonjol pada Zaman Pra-Jangkar adalah &quot;kegagalan peradaban&quot;. Karena kontradiksi inheren sistem predator, setiap peradaban yang pernah berjaya akhirnya berujung pada kehancuran diri:</p><ol><li><strong>Periode kebangkitan</strong>: Satu ras atau sekte bangkit dengan cepat melalui predasi dan mendirikan peradaban yang kuat</li><li><strong>Periode puncak</strong>: Peradaban mencapai puncak kekuatan, menekan perlawanan secara internal, dan berekspansi untuk predasi secara eksternal</li><li><strong>Periode perang internal</strong>: Orang-orang kuat di dalam peradaban saling berperang memperebutkan sumber daya terbatas, mengonsumsi kekuatan mereka</li><li><strong>Periode keruntuhan</strong>: Perang internal mengurangi kekuatan peradaban secara drastis, dan predator eksternal memanfaatkan kesempatan untuk menyerang, menyebabkan kepunahan peradaban</li><li><strong>Periode kegagalan</strong>: Setelah kepunahan peradaban, sebagian besar pengetahuan dan teknologinya hilang, dan peradaban berikutnya harus memulai dari nol</li></ol><p>Siklus &quot;kebangkitan—puncak—perang internal—keruntuhan—kegagalan&quot; ini berulang berkali-kali pada Zaman Pra-Jangkar. Setiap siklus mengonsumsi sejumlah besar esensi alam semesta, menyebabkan tingkat evolusi umum alam semesta tetap stagnan atau bahkan mundur untuk waktu yang lama.</p><h2 id="_4-tanda-tanda-akhir-zaman-pra-jangkar" tabindex="-1">4. Tanda-tanda Akhir Zaman Pra-Jangkar <a class="header-anchor" href="#_4-tanda-tanda-akhir-zaman-pra-jangkar" aria-label="Permalink to &quot;4. Tanda-tanda Akhir Zaman Pra-Jangkar&quot;">​</a></h2><p>Pada akhir Zaman Pra-Jangkar, alam semesta menunjukkan serangkaian tanda yang menandakan perubahan:</p><ul><li><strong>Memburuknya kekacauan hukum</strong>: Predasi jangka panjang merusak jaringan hukum secara parah, peristiwa keruntuhan ruang menjadi sering terjadi, dan penghalang antar-bidang menjadi lebih tipis</li><li><strong>Menipisnya potensi kehidupan</strong>: Energi dasar yang dapat dipredasi menjadi semakin langka, dan persaingan sumber daya antar orang kuat menjadi semakin sengit</li><li><strong>Tumbuhnya benih pemikiran anti-predator</strong>: Beberapa orang bijak mulai merenungkan kelemahan mendasar sistem predator dan mengusulkan konsep awal evolusi simbiosis</li><li><strong>Meningkatnya kontak antar-bidang</strong>: Menipisnya penghalang antar-bidang memungkinkan kontak yang lebih besar antar bidang yang berbeda, memungkinkan pertukaran ide antar-bidang</li><li><strong>Munculnya kandidat jangkar generasi pertama</strong>: Di beberapa sudut alam semesta, muncul makhluk khusus yang mampu beresonansi secara alami dengan jaringan hukum; mereka adalah cikal bakal dari para pembangkit jangkar generasi pertama di masa depan</li></ul><p>Tanda-tanda ini menunjukkan bahwa sistem predator telah mencapai ujungnya, dan alam semesta sedang memanggil bentuk peradaban yang sepenuhnya baru.</p><h2 id="_5-warisan-sejarah-zaman-pra-jangkar" tabindex="-1">5. Warisan Sejarah Zaman Pra-Jangkar <a class="header-anchor" href="#_5-warisan-sejarah-zaman-pra-jangkar" aria-label="Permalink to &quot;5. Warisan Sejarah Zaman Pra-Jangkar&quot;">​</a></h2><p>Meskipun Zaman Pra-Jangkar gelap, ia tidak sepenuhnya tanpa nilai. Ia meninggalkan warisan sejarah yang penting bagi peradaban simbiosis jangkar berikutnya:</p><ul><li><strong>Warisan pelajaran</strong>: Kegagalan berulang sistem predator memberikan contoh negatif yang paling mendalam bagi peradaban simbiosis, membuktikan bahwa jalan predasi tidak membawa ke mana-mana</li><li><strong>Warisan pengetahuan</strong>: Meskipun sebagian besar pengetahuan hilang dalam kegagalan peradaban, beberapa metode kultivasi dan pemahaman hukum bertahan melalui berbagai cara, menjadi sumber bahan untuk tiga ratus sistem kultivasi dasar</li><li><strong>Warisan kehidupan</strong>: Berbagai bentuk kehidupan yang bertahan hidup dalam zaman kegelapan yang panjang membentuk dasar rasial bagi simbiosis semua ras di masa depan</li><li><strong>Warisan kehendak</strong>: Keinginan terus-menerus makhluk di lapisan bawah akan keadilan dan harapan adalah kekuatan spiritual paling mendasar bagi kebangkitan jangkar</li></ul><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Zaman Pra-Jangkar adalah &quot;malam sebelum kegelapan&quot; dalam sejarah Hengyuanzhou. Panjangnya dan kegelapannya justru menonjolkan berharga dan tak terelakkannya kelahiran peradaban simbiosis jangkar. Memahami Zaman Pra-Jangkar berarti memahami akar sejarah dari posisi mendasar peradaban simbiosis &quot;menentang predasi, menganjurkan simbiosis&quot; — ini bukan khotbah moral abstrak, melainkan pelajaran darah dan air mata yang ditukar dengan kehancuran banyak peradaban.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>70-Tabel Umum Pembagian Zaman</li><li>72-Zaman Kebangkitan Jangkar</li><li>04-Program Inti Anti-Predator</li></ul>',26)])])}const o=n(t,[["render",s]]);export{p as __pageData,o as default};
